def basis(X, freq, mode):
    args = X * freq
    if mode == 0:
        return np.c_[np.ones(len(X)), np.sin(args), np.cos(args)]
    if mode == 1:
        return np.c_[np.ones(len(X)), X, np.sin(args), np.cos(args)]
    return np.c_[np.ones(len(X)), X, np.sin(args)]

def trend(X):
